# -*- coding: utf-8 -*-
"""
生成交付版《产品能力地图与技术方案》(v3)。

排版工具（字体、表格、callout、代码块、页眉页脚）直接复用 make_doc_v2.py，
只把正文换成「当前实现」，版式与上一版保持一致，评审看起来是同一份文档的改版。

用法：
    python make_doc_v3.py
输出：
    make_doc_v3.py 同目录下的 产品能力地图与技术方案.docx
"""

import os

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(HERE, "make_doc_v2.py")
PREFIX_MARK = "# ---------- 01 ----------"

with open(SRC, encoding="utf-8") as fh:
    src = fh.read()

prefix = src.split(PREFIX_MARK)[0]
prefix = prefix.replace(
    "产品文档　/　v2.0　·　2026.11",
    "产品文档　/　v3.0　·　2026.11　·　交付版",
)
prefix = prefix.replace(
    "作者 = 项目组",
    "作者 = 项目组",
)

g = {"__file__": SRC, "__name__": "__doc_prefix__"}
exec(compile(prefix, SRC + "#prefix", "exec"), g)

doc = g["doc"]
h1, h2 = g["h1"], g["h2"]
para, bullet = g["para"], g["bullet"]
T, callout = g["T"], g["callout"]
code_block = g["code_block"]
Pt, Cm = g["Pt"], g["Cm"]
WD_ALIGN_PARAGRAPH = g["WD_ALIGN_PARAGRAPH"]
set_font = g["set_font"]
BODY, LIGHT = g["BODY"], g["LIGHT"]

